import {BUILD_STEPS,SHIFT_HOURS,validateStepHours,skipsLamination} from './downstream.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function productBatchHours(values){
 const hours=Object.fromEntries(BUILD_STEPS.map(([key])=>{const value=values[key];return [key,value==null||String(value).trim()===''?null:Number(value)];}));
 validateStepHours(hours);return hours;
}
export function productLeadTimesView(s,saved=false){
 const hasTime=(p,key)=>key==='lamination'&&skipsLamination(p)||p.stepRates?.[key]!=null;
 const complete=s.parts.filter(p=>BUILD_STEPS.every(([key])=>hasTime(p,key))).length;
 return `<section class="product-lead-intro"><span class="eyebrow">PRODUCT ROUTING</span><h2>Lead times by product type.</h2><p>Enter working hours per batch. Lamination uses 20 sheets; every other step uses 20 cases. The planner scales each time to that weekly order’s quantities, including partial batches. Individual order overrides remain whole-order hours.</p></section>
 <section class="card product-lead-card"><div class="toolbar"><div><h3>Product lead times</h3><p>Hours per batch · ${SHIFT_HOURS}-hour operating days · 7 days/week before holidays</p></div><button class="primary" id="saveProductLeadTimes">Save product lead times</button></div>
 <div class="product-lead-guide"><strong>Order hours = batch hours × order quantity ÷ 20</strong><span>Lamination uses sheets; every other step uses cases. Enter 0 to bypass a step.</span></div>
 <p class="product-lead-save" role="status">${saved?'Batch times saved. Order and milestone dates have recalculated.':`${complete} of ${s.parts.length} products have all five batch times saved. Select Save product lead times to apply the displayed values.`}</p>
 <div class="scroll product-lead-scroll"><table class="product-lead-table"><thead><tr><th>Product type</th>${BUILD_STEPS.map(([key,label])=>`<th>${label}<small>Hours / 20 ${key==='lamination'?'sheets':'cases'}</small></th>`).join('')}<th>Product setup</th></tr></thead><tbody>${s.parts.map((p,i)=>{const count=BUILD_STEPS.filter(([key])=>hasTime(p,key)).length;return `<tr><td><strong>${esc(p.id)}</strong><small>${p.thickness==='thin'?'3/4"':'1 1/8"'} Akro</small></td>${BUILD_STEPS.map(([key,label])=>{const skip=key==='lamination'&&skipsLamination(p);return `<td><input type="number" min="0" max="3650" step="any" data-productlead="${i}" data-step="${key}" aria-label="${esc(p.id)} ${label} hours per 20 ${key==='lamination'?'sheets':'cases'}" value="${skip?0:p.stepRates?.[key]??''}" ${skip?'disabled':''} placeholder="Not set">${skip?'<small>Not required</small>':''}</td>`;}).join('')}<td><span class="badge ${count===BUILD_STEPS.length?'green':'amber'}">${count===BUILD_STEPS.length?'Ready':count?`${count} / ${BUILD_STEPS.length} saved`:'Not saved'}</span><small>Scaled by order quantity</small></td></tr>`;}).join('')}</tbody></table></div>
 <p class="table-footnote">OXB-787 products skip lamination. Other products use only entered times, with no automatic lamination prefill. Partial batches scale proportionally; only sheet requirements round up to whole sheets.</p>
 <p class="table-footnote">Existing whole-order times are preserved as fallbacks until replaced with batch times. Nothing is silently reinterpreted from the previous operating-day entry format. Enter case quantities in Weekly demand for case-based steps; a sheets-only order does not imply zero cases.</p>
 <p class="table-footnote">Enter production times through QC. The whole order is ready to ship when its final batch clears QC. Shipping is outside the forecast. Complete step times replace the calendar-day readiness allowance. Holidays pause all downstream steps; waterjet shutdowns pause waterjet. Waterjet pulls one 20-sheet batch at a time. Remaining sheets stay in the supermarket until the current batch is cut. Different steps overlap while each shared step processes one batch at a time across orders with complete routes, using 10-hour shifts. Case-based work scales with each batch’s share of the order. Missing routes do not reserve downstream capacity.</p>
 <button data-tab="critical">View critical-build milestones →</button></section>`;
}
